style.css:
@-moz-document domain("www.youtube.com") {
:root {
    --color: /*[[Color]]*/ ;
    --color-subscribe: /*[[Subscribe]]*/ ;
    --color-logo: /*[[Logo]]*/ ;
    --color-notify: /*[[Notify]]*/ ;
  }

  #logo-icon > span > div > svg > g > path:nth-child(1),
  #logo-icon > span > div > svg > g > path:nth-child(4) {
    fill: var(--color-logo);
  }

  .html5-video-player .ytp-play-progress,
  .html5-video-player .ytp-swatch-color-white {
    background: var(--color);
  }

  .ytp-settings-button.ytp-hd-quality-badge::after,
  .ytp-settings-button.ytp-hdr-quality-badge::after,
  .ytp-settings-button.ytp-4k-quality-badge::after,
  .ytp-settings-button.ytp-5k-quality-badge::after,
  .ytp-settings-button.ytp-8k-quality-badge::after,
  .ytp-settings-button.ytp-3d-badge-grey::after,
  .ytp-settings-button.ytp-3d-badge::after {
    background-color: var(--color);
  }

  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled {
    background: var(--color-subscribe);
  }

  .yt-spec-icon-badge-shape--type-notification-refresh
    .yt-spec-icon-badge-shape__badge {
    background-color: var(--color-notify);
  }

  .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--filled {
    background: var(--color-subscribe);
  }

  .ytp-swatch-background-color {
    background-color: var(--color-notify);
  }
}
